package ch.jalu.configme.configurationdata;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.powermock.api.support.testing.PowerMockRunner;
import org.powermock.core.classloader.annotations.PrepareForTest;
import org.powermock.modules.junit4.PowerMockRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

@RunWith(PowerMockRunner.class)
@PrepareForTest(SettingsHolder.class)
public class CommentsConfigurationTest {

    @Mock
    private SettingsHolder settingsHolderMock;

    private CommentsConfiguration commentsConfiguration;

    @Before
    public void setup() {
        commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration = new CommentsConfiguration(Arrays.asList());
    }

    @Test
    public void constructor_emptyMap_returnsEmptyCommentsConfiguration() {
        assertEquals(new HashMap<>(), commentsConfiguration.getAllComments());
    }

    @Test
    public void constructor_nonEmptyMap_returnsCommentsConfigurationWithExistingComments() {
        Map<String, List<String>> existingComments = new HashMap<>();
        existingComments.put("path1", Arrays.asList("line1", "line2"));
        when(settingsHolderMock.getComments()).thenReturn(existingComments);
        commentsConfiguration = new CommentsConfiguration(existingComments);
        assertEquals(existingComments, commentsConfiguration.getAllComments());
    }

    @Test
    public void setComment_addsCommentsForPath() {
        Map<String, List<String>> expectedComments = new HashMap<>();
        expectedComments.put("path1", Arrays.asList("line1", "line2"));
        when(settingsHolderMock.getComments()).thenReturn(expectedComments);
        commentsConfiguration.setComment("path1", "line3", "line4");
        assertEquals(expectedComments, commentsConfiguration.getAllComments());
    }

    @Test
    public void setComment_overridesExistingCommentsForPath() {
        Map<String, List<String>> existingComments = new HashMap<>();
        existingComments.put("path1", Arrays.asList("existingLine"));
        when(settingsHolderMock.getComments()).thenReturn(existingComments);
        commentsConfiguration.setComment("path1", "newLine");
        assertEquals(new HashMap<>(), commentsConfiguration.getAllComments());
    }

    @Test
    public void setComment_addsCommentsForMultiplePaths() {
        Map<String, List<String>> expectedComments = new HashMap<>();
        expectedComments.put("path1", Arrays.asList("line1", "line2"));
        expectedComments.put("path2", Arrays.asList("line3", "line4"));
        when(settingsHolderMock.getComments()).thenReturn(expectedComments);
        commentsConfiguration.setComment("path1", "line5", "line6");
        assertEquals(expectedComments, commentsConfiguration.getAllComments());
    }

    @Test
    public void setComment_addsEmptyLineWithoutCommentMarker() {
        Map<String, List<String>> expectedComments = new HashMap<>();
        expectedComments.put("path1", Arrays.asList(""));
        when(settingsHolderMock.getComments()).thenReturn(expectedComments);
        commentsConfiguration.setComment("path1");
        assertEquals(expectedComments, commentsConfiguration.getAllComments());
    }

    @Test
    public void getAllComments_returnsUnmodifiableView() {
        Map<String, List<String>> expectedComments = new HashMap<>();
        expectedComments.put("path1", Arrays.asList("line1"));
        commentsConfiguration.setComment("path1", "line2");
        assertEquals(expectedComments, commentsConfiguration.getAllComments());
        assertTrue(commentsConfiguration.getAllComments().isEmpty());
    }

    @Test
    public void setComment_withNullPath_throwsNullPointerException() {
        assertThrows(NullPointerException.class, () -> commentsConfiguration.setComment(null, "line"));
    }
}
